namespace sv_86ef42a76c064c33aedf72956e9fb5b1.Services;

/// <summary>
/// Scoped service (per-circuit) that holds the current warehouse selection
/// and low-stock alert count, with change-notification events so any
/// subscribing component can re-render when state changes.
/// </summary>
public sealed class WarehouseStateService : IDisposable
{
    private string _currentWarehouseId = "WH-001";
    private int _lowStockCount;

    public string CurrentWarehouseId
    {
        get => _currentWarehouseId;
        set
        {
            if (_currentWarehouseId == value) return;
            _currentWarehouseId = value;
            NotifyWarehouseChanged();
        }
    }

    public string CurrentWarehouseName =>
        AvailableWarehouses.FirstOrDefault(w => w.Id == _currentWarehouseId)?.Name
        ?? _currentWarehouseId;

    public int LowStockCount
    {
        get => _lowStockCount;
        set
        {
            if (_lowStockCount == value) return;
            _lowStockCount = value;
            NotifyAlertCountChanged();
        }
    }

    public static IReadOnlyList<Warehouse> AvailableWarehouses { get; } =
    [
        new("WH-001", "Warehouse A — Main Distribution"),
        new("WH-002", "Warehouse B — East Regional"),
        new("WH-003", "Warehouse C — West Regional"),
        new("WH-004", "Warehouse D — Returns Processing"),
    ];

    /// <summary>Raised when the selected warehouse changes.</summary>
    public event Action? OnWarehouseChanged;

    /// <summary>Raised when the low-stock alert count is updated.</summary>
    public event Action? OnAlertCountChanged;

    private void NotifyWarehouseChanged() => OnWarehouseChanged?.Invoke();
    private void NotifyAlertCountChanged() => OnAlertCountChanged?.Invoke();

    public void Dispose()
    {
        OnWarehouseChanged = null;
        OnAlertCountChanged = null;
    }

    public record Warehouse(string Id, string Name);
}

namespace sv_86ef42a76c064c33aedf72956e9fb5b1.Services;

/// <summary>
/// Simulates a database query for low-stock items.
/// Scoped per circuit so each user has independent randomness.
/// </summary>
public sealed class InventoryAlertService
{
    private readonly Random _random = new();

    /// <summary>
    /// Returns a simulated count of items below minimum stock levels
    /// for the given warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate async database call
        var count = _random.Next(0, 16); // 0–15 inclusive
        return Task.FromResult(count);
    }
}

@using sv_86ef42a76c064c33aedf72956e9fb5b1.Services
@inject WarehouseStateService State
@implements IDisposable

<div class="warehouse-selector">
    <label class="form-label text-white mb-1 small">Current Warehouse</label>
    <select class="form-select form-select-sm"
            value="@State.CurrentWarehouseId"
            @onchange="OnWarehouseSelected">
        @foreach (var wh in WarehouseStateService.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    private void OnWarehouseSelected(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            State.CurrentWarehouseId = newId;
        }
    }

    protected override void OnInitialized()
    {
        State.OnWarehouseChanged += StateHasChanged;
    }

    public void Dispose()
    {
        State.OnWarehouseChanged -= StateHasChanged;
    }
}

@using sv_86ef42a76c064c33aedf72956e9fb5b1.Services
@inject WarehouseStateService State
@implements IDisposable

<span class="badge @BadgeClass rounded-pill">@State.LowStockCount</span>

@code {
    private string BadgeClass => State.LowStockCount switch
    {
        0 => "bg-success",
        <= 5 => "bg-warning text-dark",
        _ => "bg-danger"
    };

    protected override void OnInitialized()
    {
        State.OnAlertCountChanged += OnStateChanged;
        State.OnWarehouseChanged += OnStateChanged;
    }

    private void OnStateChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        State.OnAlertCountChanged -= OnStateChanged;
        State.OnWarehouseChanged -= OnStateChanged;
    }
}

@page "/dashboard"
@rendermode InteractiveServer
@using sv_86ef42a76c064c33aedf72956e9fb5b1.Services
@inject WarehouseStateService State
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard — @State.CurrentWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card border-@CardBorder">
            <div class="card-header">
                <strong>Low-Stock Alerts</strong>
            </div>
            <div class="card-body text-center">
                <h2 class="display-4 text-@CardBorder">@State.LowStockCount</h2>
                <p class="text-muted">items below minimum level</p>
            </div>
            <div class="card-footer text-muted small">
                Polling every 10s &mdash; Last checked: @_lastChecked?.ToString("HH:mm:ss")
            </div>
        </div>
    </div>

    <div class="col-md-8">
        <div class="card">
            <div class="card-header">
                <strong>Active Warehouse</strong>
            </div>
            <div class="card-body">
                <dl class="row mb-0">
                    <dt class="col-sm-4">Warehouse ID</dt>
                    <dd class="col-sm-8"><code>@State.CurrentWarehouseId</code></dd>
                    <dt class="col-sm-4">Name</dt>
                    <dd class="col-sm-8">@State.CurrentWarehouseName</dd>
                    <dt class="col-sm-4">Status</dt>
                    <dd class="col-sm-8"><span class="badge bg-success">Online</span></dd>
                </dl>
            </div>
        </div>
    </div>
</div>

@code {
    private Timer? _pollingTimer;
    private DateTime? _lastChecked;

    private string CardBorder => State.LowStockCount switch
    {
        0 => "success",
        <= 5 => "warning",
        _ => "danger"
    };

    protected override async Task OnInitializedAsync()
    {
        State.OnWarehouseChanged += OnWarehouseChanged;
        State.OnAlertCountChanged += OnAlertCountChanged;

        // Initial fetch
        await PollAlerts();

        // Start polling every 10 seconds
        _pollingTimer = new Timer(async _ => await PollAlerts(), null,
            TimeSpan.FromSeconds(10), TimeSpan.FromSeconds(10));
    }

    private async void OnWarehouseChanged()
    {
        // Immediately refresh alerts when warehouse changes
        await PollAlerts();
        await InvokeAsync(StateHasChanged);
    }

    private void OnAlertCountChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private async Task PollAlerts()
    {
        var count = await AlertService.GetLowStockCountAsync(State.CurrentWarehouseId);
        _lastChecked = DateTime.Now;
        // Setting this property fires OnAlertCountChanged, notifying ALL subscribers
        State.LowStockCount = count;
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        _pollingTimer?.Dispose();
        State.OnWarehouseChanged -= OnWarehouseChanged;
        State.OnAlertCountChanged -= OnAlertCountChanged;
    }
}

