namespace sv_86ef42a76c064c33aedf72956e9fb5b1.Services;

/// <summary>
/// Scoped service (per-circuit) that holds the current warehouse selection
/// and low-stock alert count, with change-notification events so any
/// subscribing component can re-render when state changes.
/// </summary>
public sealed class WarehouseStateService : IDisposable
{
    private string _currentWarehouseId = "WH-001";
    private int _lowStockCount;

    public string CurrentWarehouseId
    {
        get => _currentWarehouseId;
        set
        {
            if (_currentWarehouseId == value) return;
            _currentWarehouseId = value;
            NotifyWarehouseChanged();
        }
    }

    public string CurrentWarehouseName =>
        AvailableWarehouses.FirstOrDefault(w => w.Id == _currentWarehouseId)?.Name
        ?? _currentWarehouseId;

    public int LowStockCount
    {
        get => _lowStockCount;
        set
        {
            if (_lowStockCount == value) return;
            _lowStockCount = value;
            NotifyAlertCountChanged();
        }
    }

    public static IReadOnlyList<Warehouse> AvailableWarehouses { get; } =
    [
        new("WH-001", "Warehouse A — Main Distribution"),
        new("WH-002", "Warehouse B — East Regional"),
        new("WH-003", "Warehouse C — West Regional"),
        new("WH-004", "Warehouse D — Returns Processing"),
    ];

    /// <summary>Raised when the selected warehouse changes.</summary>
    public event Action? OnWarehouseChanged;

    /// <summary>Raised when the low-stock alert count is updated.</summary>
    public event Action? OnAlertCountChanged;

    private void NotifyWarehouseChanged() => OnWarehouseChanged?.Invoke();
    private void NotifyAlertCountChanged() => OnAlertCountChanged?.Invoke();

    public void Dispose()
    {
        OnWarehouseChanged = null;
        OnAlertCountChanged = null;
    }

    public record Warehouse(string Id, string Name);
}

